   874	/**
   875	 * Read a RAR5 variable sized numeric value. This value will be stored in
   876	 * `pvalue`. The `pvalue_len` argument points to a variable that will receive
   877	 * the byte count that was consumed in order to decode the `pvalue` value, plus
   878	 * one.
   879	 *
   880	 * pvalue_len is optional and can be NULL.
   881	 *
   882	 * NOTE: if `pvalue_len` is NOT NULL, the caller needs to manually consume
   883	 * the number of bytes that `pvalue_len` value contains. If the `pvalue_len`
   884	 * is NULL, this consuming operation is done automatically.
   885	 *
   886	 * Returns 1 if *pvalue was successfully read.
   887	 * Returns 0 if there was an error. In this case, *pvalue contains an
   888	 *           invalid value.
   889	 */
   890	
   891	static int read_var(struct archive_read* a, uint64_t* pvalue,
   892	        uint64_t* pvalue_len)
   893	{
   894	    uint64_t result = 0;
   895	    size_t shift, i;
   896	    const uint8_t* p;
   897	    uint8_t b;
   898	
   899	    /* We will read maximum of 8 bytes. We don't have to handle the situation
   900	     * to read the RAR5 variable-sized value stored at the end of the file,
   901	     * because such situation will never happen. */
   902	    if(!read_ahead(a, 8, &p))
   903	        return 0;
   904	
   905	    for(shift = 0, i = 0; i < 8; i++, shift += 7) {
   906	        b = p[i];
   907	
   908	        /* Strip the MSB from the input byte and add the resulting number
   909	         * to the `result`. */
   910	        result += (b & (uint64_t)0x7F) << shift;
   911	
   912	        /* MSB set to 1 means we need to continue decoding process. MSB set
   913	         * to 0 means we're done.
   914	         *
   915	         * This conditional checks for the second case. */
   916	        if((b & 0x80) == 0) {
   917	            if(pvalue) {
   918	                *pvalue = result;
   919	            }
   920	
   921	            /* If the caller has passed the `pvalue_len` pointer, store the
   922	             * number of consumed bytes in it and do NOT consume those bytes,
   923	             * since the caller has all the information it needs to perform
   924	             * the consuming process itself. */
   925	            if(pvalue_len) {
   926	                *pvalue_len = 1 + i;
   927	            } else {
   928	                /* If the caller did not provide the `pvalue_len` pointer,
   929	                 * it will not have the possibility to advance the file
   930	                 * pointer, because it will not know how many bytes it needs
   931	                 * to consume. This is why we handle such situation here
   932	                 * automatically. */
   933	                if(ARCHIVE_OK != consume(a, 1 + i)) {
   934	                    return 0;
   935	                }
   936	            }
   937	
   938	            /* End of decoding process, return success. */
   939	            return 1;
   940	        }
   941	    }
   942	
   943	    /* The decoded value takes the maximum number of 8 bytes. It's a maximum
   944	     * number of bytes, so end decoding process here even if the first bit
   945	     * of last byte is 1. */
   946	    if(pvalue) {
   947	        *pvalue = result;
   948	    }
   949	
   950	    if(pvalue_len) {
   951	        *pvalue_len = 9;
   952	    } else {
   953	        if(ARCHIVE_OK != consume(a, 9)) {
   954	            return 0;
   955	        }
   956	    }
   957	
   958	    return 1;
   959	}
