   961	static int read_var_sized(struct archive_read* a, size_t* pvalue,
   962	        size_t* pvalue_len)
   963	{
   964	    uint64_t v;
   965	    uint64_t v_size = 0;
   966	
   967	    const int ret = pvalue_len
   968	                    ? read_var(a, &v, &v_size)
   969	                    : read_var(a, &v, NULL);
   970	
   971	    if(ret == 1 && pvalue) {
   972	        *pvalue = (size_t) v;
   973	    }
   974	
   975	    if(pvalue_len) {
   976	        /* Possible data truncation should be safe. */
   977	        *pvalue_len = (size_t) v_size;
   978	    }
   979	
   980	    return ret;
   981	}
