   983	static int read_bits_32(struct rar5* rar, const uint8_t* p, uint32_t* value) {
   984	    uint32_t bits = p[rar->bits.in_addr] << 24;
   985	    bits |= p[rar->bits.in_addr + 1] << 16;
   986	    bits |= p[rar->bits.in_addr + 2] << 8;
   987	    bits |= p[rar->bits.in_addr + 3];
   988	    bits <<= rar->bits.bit_addr;
   989	    bits |= p[rar->bits.in_addr + 4] >> (8 - rar->bits.bit_addr);
   990	    *value = bits;
   991	    return ARCHIVE_OK;
   992	}
