   994	static int read_bits_16(struct rar5* rar, const uint8_t* p, uint16_t* value) {
   995	    int bits = (int) p[rar->bits.in_addr] << 16;
   996	    bits |= (int) p[rar->bits.in_addr + 1] << 8;
   997	    bits |= (int) p[rar->bits.in_addr + 2];
   998	    bits >>= (8 - rar->bits.bit_addr);
   999	    *value = bits & 0xffff;
  1000	    return ARCHIVE_OK;
